package com.myriam.unrp.ability;

import java.util.regex.Pattern;

/** Canonical, typed special laws: effect text is generated by the form, never evaluated as code. */
public final class CovenantSpecificRules {
    public enum Kind { SIGNED_CONTRACTS, HOME_REPORT }
    public record Rule(Kind kind,String target) {
        public boolean matches(String name) {return target.equals("*")||target.equalsIgnoreCase(name);}
        public String text() {return kind==Kind.SIGNED_CONTRACTS?"Transfer signed contracts to the Sovereign."
                :"When "+target+" enters the Court, record their home in a book for the Sovereign.";}
    }
    private static final Pattern HOME=Pattern.compile("When ([A-Za-z0-9_]{1,16}|\\*) enters the Court, record their home in a book for the Sovereign\\.",Pattern.CASE_INSENSITIVE);
    private CovenantSpecificRules() {}
    public static Rule parse(String text) {
        if(text.trim().equalsIgnoreCase("Transfer signed contracts to the Sovereign."))return new Rule(Kind.SIGNED_CONTRACTS,"*");
        var match=HOME.matcher(text.trim());
        return match.matches()?new Rule(Kind.HOME_REPORT,match.group(1)):null;
    }
}
